<template>
	<div class="layout">
		<div class="download-offline-buttons">
			<button
				type="button"
				:disabled="loadingDownloaded || downloading || downloadData.remaining === 0"
				@click="downloadForOfflineUsage"
			>
				<span>Mode offline</span>
				<span v-if="loadingDownloaded">(...)</span>
				<span v-else>({{ Number(progressCacheDownload).toFixed(2) }} %)</span>
			</button>
			<button
				type="button"
				:disabled="loadingDownloaded || downloadData.remaining === downloadData.total"
				@click="deleteDownloadedData"
			>
				<span>Supp. stockage offline</span>
			</button>
		</div>
		<div>
			<router-view />
		</div>
	</div>
</template>

<script setup>
import { onMounted, computed, reactive, ref } from 'vue'
// const baseUrl = 'https://pub-4211d6b528d54ed69e8ec217f023723e.r2.dev/'
const downloadData = reactive({
	total: 0,
	remaining: 0,
})

const loadingDownloaded = ref(true)
const downloading = ref(false)
const progressCacheDownload = computed(() => ((downloadData.total - downloadData.remaining) / downloadData.total) * 100)

async function calcPercentDownloaded() {
	const worker = new Worker(new URL('@/workers/calc-data-offline.js', import.meta.url), {
		name: 'calc-data-offline',
		type: 'module',
	})
	const onMessage = ev => {
		if (ev.data?.cache || 'cached' in ev.data) worker.postMessage({ sw: ev.data })
	}
	navigator.serviceWorker.addEventListener('message', onMessage)
	const { total, remaining, sets } = await new Promise(resolve => {
		worker.onmessage = ev => {
			if (ev.data?.sw) navigator.serviceWorker.controller.postMessage(ev.data?.sw)
			else if (ev.data.resolve) {
				resolve(ev.data.resolve)
			}
		}
	})
	await worker.terminate()
	progressCacheDownload.value = ((total - remaining) / total) * 100
	downloadData.remaining = remaining
	downloadData.total = total
}

async function downloadForOfflineUsage() {
	if (downloading.value) return
	if (navigator.storage && navigator.storage.persist) await navigator.storage.persist()
	downloading.value = true
	const worker = new Worker(new URL('@/workers/download-data-offline.js', import.meta.url), {
		name: 'download-data-offline',
		type: 'module',
	})
	const onMessage = ev => {
		if (ev.data?.cache || 'cached' in ev.data) worker.postMessage({ sw: ev.data })
	}
	navigator.serviceWorker.addEventListener('message', onMessage)
	await new Promise(resolve => {
		worker.onmessage = ev => {
			if (ev.data?.sw) navigator.serviceWorker.controller.postMessage(ev.data?.sw)
			else if (ev.data.resolve) {
				resolve(ev.data.resolve)
			} else if (ev.data.progress) {
				downloadData.remaining -= ev.data.progress.downloaded
			}
		}
	}).catch(() => {})
	downloading.value = false
}

function deleteDownloadedData() {
	navigator.serviceWorker.controller.postMessage({ removeCache: 'images' })
	downloadData.remaining = downloadData.total
}

onMounted(() => {
	calcPercentDownloaded().then(() => {
		loadingDownloaded.value = false
	})
})
