import { normalize } from '@common/utils'

/** @type {IDBDatabase} */
let db

/**
 * Open the App IndexedDB and do the migrations
 */
const openCardsDB = () => new Promise((resolve, reject) => {
	const request = indexedDB.open('app', 1)
	request.onupgradeneeded = ev => {
		const db = request.result
		if (!ev.oldVersion) {
			db.createObjectStore('cards')
			db.createObjectStore('abilities')
			db.createObjectStore('attacks')
		}
	}
	request.onerror = () => {
		console.error('[indexeddb]', request.error)
		reject(request.error)
	}
	request.onsuccess = ev => {
		resolve(ev.target.result)
	}
})

/**
 *
 * @param {IDBDatabase} db
 * @param {String|String[]} name
 * @param {IDBTransactionMode} mode
 * @param {(store: IDBObjectStore) => void} callback
 * @returns {Promise<IDBObjectStore>}
 */
const doInStore = (db, name, mode, callback) => new Promise((resolve, reject) => {
	const tr = db.transaction(name, mode)
	tr.oncomplete = resolve
	tr.onerror = reject
	callback(tr.objectStore(name))
})

const initProcess = Promise.all([
	typeof window !== 'undefined' ? fetch('./db.json', { cache: 'no-cache' }).then(res => res.json()).catch(() => null) : Promise.resolve(),
	openCardsDB(),
])

export const processStore = async (name, ...args) => {
	await initProcess
	
	let options = {}
	if (typeof args[1] === 'object') options = args[1]
	const fn = args.pop()
	return doInStore(db, name, options.mode || 'readonly', fn)
}

initProcess.then(async ([cards, _db]) => {
	/** @type {IDBDatabase} */
	db = _db
	if (!cards) return

	// Filling database with all the cards
	// TODO: Do the update in a separate process, and dont fetch always all the cards
	await doInStore(db, 'cards', 'readwrite', store => {
		for (const card of cards) {
			card.search = [
				card.id,
				`${card.ext} ${card.extId}`,
				normalize(card.fr?.name || ''),
				normalize(card.en?.name || ''),
			].filter(s => !!s).map(s => s.trim()).join('\n')

			store.put(card, card.id)
		}
	})
})